def run_rebco_conductor_current(inputs: REBCO_Conductor_CurrentInput) -> tuple[float, float, float, float, float, float, float, float, float, float, float]:
    def positive(key, value):
        if not math.isfinite(value) or value <= 0:
            raise ValueError(f'REBCO Conductor Current: {key} must be finite and positive')
        return value

    for key in type(inputs).model_fields:
        value = getattr(inputs, key)
        if key == 'allow_field_extrapolation':
            if value not in (0.0, 1.0):
                raise ValueError('REBCO Conductor Current: allow_field_extrapolation must be 0 or 1')
        else:
            positive(key, value)
    for key in ('cabling_factor', 'degradation_factor', 'sharing_factor', 'allowable_fraction'):
        if getattr(inputs, key) > 1:
            raise ValueError(f'REBCO Conductor Current: {key} must be at most 1')
    for key, target in (('temperature', 20.0), ('tape_thickness', 56e-6)):
        if getattr(inputs, key) != target:
            unit = 'K' if key == 'temperature' else 'm'
            raise ValueError(f'REBCO Conductor Current: unsupported {key}={getattr(inputs, key)!r} {unit}; expected {target} {unit}')
    if not 0.004 <= inputs.tape_width <= 0.006:
        raise ValueError(f'REBCO Conductor Current: tape_width outside 4..6 mm; actual={inputs.tape_width!r} m')
    if not 20 <= inputs.B_peak <= 32:
        raise ValueError(f'REBCO Conductor Current: B_peak outside 20..32 T; actual={inputs.B_peak!r} T at {inputs.temperature!r} K')
    extrapolated = float(inputs.B_peak > 24)
    if extrapolated and not inputs.allow_field_extrapolation:
        raise ValueError(f'REBCO Conductor Current: B_peak above 24 T requires allow_field_extrapolation; actual={inputs.B_peak!r} T; supported without extrapolation=20..24 T')
    out = {}
    out['parallel_tapes_set'] = positive('parallel_tapes_set', inputs.tape_length / inputs.conductor_length)
    intermediate = positive('reference_count_numerator', out['parallel_tapes_set'] * inputs.f_set)

def run_conductor_peak_field(inputs: Conductor_Peak_FieldInput) -> float:
    """Return signed conductor field, refusing invalid clearance first."""
    if not inputs.R_in - inputs.a_coil_in > 0:
        raise ValueError('Conductor Peak Field: live clearance R_in - a_coil_in must be > 0')
    if not inputs.R_ref_in - inputs.a_coil_ref_in > 0:
        raise ValueError('Conductor Peak Field: reference clearance R_ref_in - a_coil_ref_in must be > 0')
    bore_factor = inputs.R_in / (inputs.R_in - inputs.a_coil_in)
    bore_factor_ref = inputs.R_ref_in / (inputs.R_ref_in - inputs.a_coil_ref_in)
    bore_norm = bore_factor / bore_factor_ref
    return (inputs.B_axis_in * inputs.peak_ratio_in) * bore_norm

FIELDS = ['actual_suction_K', 'rated_suction_K', 'actual_suction_Pa', 'rated_suction_Pa', 'actual_discharge_Pa', 'rated_discharge_Pa', 'actual_hot_K', 'rated_hot_K', 'actual_cp', 'rated_cp', 'actual_gamma', 'rated_gamma']
PAIRS = ['suction_K', 'suction_Pa', 'discharge_Pa', 'hot_K', 'cp', 'gamma']
def same_state(a, b):
    # Reviewed binary representation identity; never a physical operating envelope.
    return math.isfinite(a) and math.isfinite(b) and (
        a == b or abs(a-b) <= 8 * max(math.ulp(a), math.ulp(b)))
def calculate(x):
    if not isinstance(x['enabled'], bool):
        raise ValueError('enabled must be Boolean')
    if isinstance(x['mode'],bool) or x['mode'] not in (0.0,1.0):
        raise ValueError('mode must be exactly zero or one')
    if not x['enabled'] or x['mode'] == 0.0:
        return dict(applicable=False, supported=False, evaluation_defined=0.0)
    for key in FIELDS:
        if isinstance(x[key], bool) or not math.isfinite(x[key]):
            raise ValueError(key + ' must be finite numeric')
    supported = all(same_state(x['actual_'+key], x['rated_'+key]) for key in PAIRS)
    return dict(applicable=True, supported=supported, evaluation_defined=1.0 if supported else 0.0)
